/* ---------- widget: separation game ---------- */
function onTheory(root){const w=root.querySelector('#w-sep');if(!w)return;
  let st;
  const NM={sand:'песок',salt:'соль',iron:'железные опилки'};
  const reset=()=>{st={mix:['sand','salt','iron'],water:false,got:[],log:['В стакане сухая смесь: песок + соль + железные опилки.']};draw();};
  const say=s=>st.log.push(s);
  const act={
    magnet(){if(st.mix.includes('iron')){st.mix=st.mix.filter(x=>x!=='iron');st.got.push(['железные опилки',true]);say(st.water?'Магнит вытащил опилки, но они мокрые — придётся сушить, а то заржавеют.':'Магнит притянул железные опилки. Отлично!');}else say('Магнит ничего не притягивает: железа в смеси нет.');},
    water(){if(st.water){say('Вода уже налита.');return;}st.water=true;say(st.mix.includes('salt')?'Налили воду и перемешали: соль растворилась, песок'+(st.mix.includes('iron')?' и опилки лежат':' лежит')+' на дне.':'Налили воду.');},
    filter(){if(!st.water){say('Сухую смесь фильтровать бессмысленно — сначала добавь воду.');return;}const ins=st.mix.filter(x=>x!=='salt');if(!ins.length){say('Нерастворимого ничего нет — фильтр ничего не задержит.');return;}
      st.mix=st.mix.filter(x=>x==='salt');const clean=ins.length===1;st.got.push([ins.map(x=>NM[x]).join(' + '),clean]);say(clean?'На фильтре остался песок, через фильтр прошёл раствор соли.':'На фильтре — песок вместе с опилками. Это снова смесь! Надо было раньше взять магнит.');},
    evap(){if(!st.water||!st.mix.length){say('Выпаривать нечего.');return;}const clean=st.mix.length===1&&st.mix[0]==='salt';st.got.push([st.mix.map(x=>NM[x]).join(' + '),clean]);
      say(clean?'Вода испарилась — в чашке белые кристаллы соли!':'Вода испарилась, но соль перемешана с '+st.mix.filter(x=>x!=='salt').map(x=>NM[x]).join(' и ')+' — снова смесь.');st.mix=[];st.water=false;}
  };
  w.innerHTML=`<div style="display:flex;flex-wrap:wrap;gap:8px"><button class="btn ghost" data-a="magnet">🧲 Магнит</button><button class="btn ghost" data-a="water">💧 Добавить воду</button><button class="btn ghost" data-a="filter">⏬ Фильтровать</button><button class="btn ghost" data-a="evap">🔥 Выпарить</button><button class="btn ghost" data-a="reset">↺ Сначала</button></div><div id="wsS" style="margin-top:10px"></div>`;
  const draw=()=>{const ok=st.got.filter(g=>g[1]).length;
    const left=st.mix.length?st.mix.map(x=>NM[x]).join(' + ')+(st.water?' (в воде)':''):(st.water?'вода':'пусто');
    w.querySelector('#wsS').innerHTML=`<div style="font-size:15px">В стакане: <span class="out">${left}</span></div><div style="font-size:15px">Получено: ${st.got.length?st.got.map(g=>`<span style="color:${g[1]?'var(--ok)':'var(--bad)'};font-weight:700">${g[0]}${g[1]?' ✓':' ✗'}</span>`).join(', '):'—'}</div><div style="margin-top:6px">${st.log.slice(-3).map(s=>`<div style="font-size:15px">• ${s}</div>`).join('')}</div>${ok===3?'<div class="out" style="margin-top:6px">Победа! Все три вещества выделены в чистом виде.</div>':''}`;};
  w.querySelectorAll('button').forEach(b=>b.onclick=()=>{const a=b.dataset.a;if(a==='reset')reset();else{act[a]();draw();}});
  reset();}

/* =================== GENERATORS =================== */
/* L0 тела и вещества */
RULE(0,'Что такое вещество?','То, из чего состоят физические тела',['Любой предмет, который можно взять в руки','Только жидкости и газы','Всё, что имеет форму и размер'],
{short:'Вещество — это материал, из которого сделано тело.',
explain:'<b>Тело</b> — конкретный предмет (гвоздь, стакан). <b>Вещество</b> — то, из чего он состоит (железо, стекло). Предмет, который можно взять в руки, и «всё, что имеет форму», — это как раз тела. Вещества бывают твёрдыми, жидкими и газообразными.',
explain2:'Спроси: «Из чего?» Из чего сделан гвоздь? Из железа. Железо — вещество. А гвоздь — тело.'});
RULE(0,'Чем тело отличается от вещества?','Тело — конкретный предмет, а вещество — материал, из которого этот предмет состоит',['Тело всегда твёрдое, а вещество всегда жидкое','Тело — это живой организм, а вещество — неживое','Ничем: это одно и то же'],
{short:'Тело — «что это?», вещество — «из чего?».',
explain:'Тело — предмет с формой и размером: ложка, сосулька, капля. Вещество — то, из чего этот предмет: сталь, вода. Тело не обязательно твёрдое (капля — тело), а вещество бывает и твёрдым (железо). «Тело» в физике — не только живой организм.',
explain2:'Пример: сосулька и капля — два разных тела, но вещество у них одно — вода.'});
G(0,()=>{const p=pick(BODY);const opts=['Тело','Вещество'];
return {type:'choice',q:`«<b>${cap(p[0])}</b>» — это физическое тело или вещество?`,opts,ans:p[1],short:p[1]?`${cap(p[0])} — это материал, из него делают разные предметы.`:`${cap(p[0])} — конкретный предмет.`,
explain:`${p[1]?`«${cap(p[0])}» отвечает на вопрос «<b>из чего</b> сделано?» — это <b>вещество</b>. Из него можно сделать много разных тел.`:`«${cap(p[0])}» — конкретный предмет, его можно сосчитать («один, два…»), у него есть форма и размер. Это <b>тело</b>.`}`,
explain2:`Попробуй сказать «один ${p[0]}, два…». ${p[1]?'Звучит странно? Значит, это вещество — материал без определённой формы.':'Получается? Значит, это тело (предмет).'}`};});
G(0,()=>{const pos=BODY.filter(x=>x[1]).map(x=>[x[0]]),neg=BODY.filter(x=>!x[1]).map(x=>[x[0]]);const t=MU('Отметь все <b>вещества</b> (а не тела).',pos,neg,6);
const vs=t._items.filter(x=>x[1]).map(x=>x[0][0]),ts=t._items.filter(x=>!x[1]).map(x=>x[0][0]);delete t._items;
return Object.assign(t,{short:`Вещества: ${vs.join(', ')}.`,explain:`Вещества — это материалы: <b>${vs.join(', ')}</b>. Остальное — конкретные предметы, то есть тела: ${ts.join(', ')}.`,explain2:`Для каждого слова спроси «из чего это?». Если вопрос не подходит (из чего железо? — это и есть материал) — перед тобой вещество. Тела: ${ts.join(', ')}.`});});
G(0,()=>{const P=[['экран смартфона','стекло'],['корпус банки для газировки','алюминий'],['провод в зарядке','медь'],['грифель карандаша','графит'],['сосулька','вода'],['гвоздь','железо'],['обручальное кольцо','золото'],['микросхема процессора','кремний']];
const p=pick(P);const others=sample(P.filter(x=>x[1]!==p[1]).map(x=>x[1]),3);
return CH(`Из какого вещества обычно состоит это тело: <b>${p[0]}</b>?`,p[1],others,{short:`${cap(p[0])} — тело, ${p[1]} — вещество.`,
explain:`${cap(p[0])} — это <b>тело</b> (предмет). Вещество, из которого его обычно делают, — <b>${p[1]}</b>. Остальные варианты — тоже вещества, но из них делают другие вещи.`,
explain2:`Вспомни, как выглядит ${p[0]} и какие у него свойства. ${p[1]==='медь'?'Провода должны хорошо проводить ток — медь в этом почти лучшая.':p[1]==='алюминий'?'Банка лёгкая и не ржавеет — это алюминий.':p[1]==='графит'?'Грифель мягкий, чёрный и пачкает бумагу — графит.':p[1]==='вода'?'Сосулька тает и превращается в воду.':p[1]==='кремний'?'Процессоры делают из очень чистого кремния — поэтому «Кремниевая долина».':p[1]==='стекло'?'Экран прозрачный и твёрдый — особое стекло.':p[1]==='золото'?'Кольцо жёлтое, блестит и не ржавеет — золото.':'Гвоздь притягивается магнитом и ржавеет — железо.'}`});});

